(()=>{
 'use strict';
 const C=window.DEMO_CONTEXT,A=window.DEMO_INTERACTION_ASSETS,P=window.DEMO_PAGE;if(!C?.openNativeForm)return;
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],norm=s=>(s||'').replace(/\s+/g,'');
 const layoutHosts=new WeakMap();
 const layoutKey='blacklake-layout-v3-'+P.id;let layouts=[];try{layouts=JSON.parse(localStorage.getItem(layoutKey)||'[]');}catch{}
 const layoutPage=/D-PASSIVE-BL-10-(01|04)-readpanel02/.test(P.id),rulePage=P.id==='D-PASSIVE-BL-04-04-timerules';
 function timePicker(input){const panel=C.openPortal(A.components.timePicker,input,'time'),native=$('.kodo-new-picker-dropdown',panel);if(native)native.style.cssText='position:static;inset:auto;transform:none';let [hour,minute]=(input.value||'00:00').split(':');panel.addEventListener('click',e=>{const item=e.target.closest('.kodo-new-picker-time-panel-cell');if(item){const column=item.closest('.kodo-new-picker-time-panel-column'),index=$$('.kodo-new-picker-time-panel-column',panel).indexOf(column);if(index===0)hour=item.textContent.trim();else minute=item.textContent.trim();$$('.kodo-new-picker-time-panel-cell',column).forEach(li=>li.classList.toggle('kodo-new-picker-time-panel-cell-selected',li===item));}if(e.target.closest('button')){input.value=hour+':'+minute;input.dispatchEvent(new Event('input',{bubbles:true}));C.dismissPortal();}});}
 function readLayoutValues(d){return $$('.fieldName__OVYm2',d).map(e=>e.textContent.trim());}
 function wireLayout(d){const row=$('.fieldRow__oMsKW',d);if(row)layoutHosts.set(d,row.parentElement);const host=layoutHosts.get(d);if(host){host.ondragover=event=>event.preventDefault();host.ondrop=event=>{const from=$('[data-layout-drag]',d);if(from?.classList.contains('dragField__uQ02L')){event.preventDefault();addField(d,from.textContent.trim());}};}
  const search=$('input[placeholder="输入字段名"]',d);if(search)search.oninput=()=>$$('.dragField__uQ02L',d).forEach(e=>e.style.display=e.textContent.includes(search.value)?'':'none');
  $$('.fieldRow__oMsKW,.dragField__uQ02L:not(.canNotDrag___oFnX)',d).forEach(e=>{e.draggable=true;e.ondragstart=event=>{e.dataset.layoutDrag='1';event.dataTransfer.setData('text/plain',e.textContent.trim());};e.ondragend=()=>delete e.dataset.layoutDrag;});
  $$('.fieldRow__oMsKW',d).forEach(e=>{e.ondragover=event=>event.preventDefault();e.ondrop=event=>{event.preventDefault();const from=$('[data-layout-drag]',d);if(from?.classList.contains('fieldRow__oMsKW'))e.before(from);else if(from)addField(d,from.textContent.trim(),e);};});
 }
 function addField(d,text,before){if(!text||readLayoutValues(d).includes(text))return;const holder=document.createElement('div');holder.innerHTML=A.components.layoutFieldRow;const row=holder.firstElementChild;$('.fieldName__OVYm2',row).textContent=text;if(before)before.before(row);else{const existing=$$('.fieldRow__oMsKW',d);if(existing.length)existing.at(-1).after(row);else layoutHosts.get(d)?.append(row);}wireLayout(d);}
 function layoutEditor(anchor,record){const name=P.id.includes('10-04')?'layoutWO':'layoutProduct';C.openNativeForm(name,anchor,values=>{if(record)record.values=values;else layouts.push({id:'L-'+Date.now(),values});localStorage.setItem(layoutKey,JSON.stringify(layouts));renderLayouts();},record?.values||{});}
 function renderLayouts(){if(!layoutPage)return;const d=$$('[role=dialog]').at(-1)||document,table=$('.kodo-art-table',d),body=table&&$('.kodo-art-table-tbody',table),head=table&&$('.kodo-art-table-thead .kodo-art-table-row',table);if(!body||!head)return;$$('span,div',d).filter(e=>!e.children.length&&/^已创建\d+条，最多创建\d+条$/.test(e.textContent.trim())).forEach(e=>e.textContent=e.textContent.replace(/^已创建\d+/, '已创建'+layouts.length));if(!layouts.length){$$('[data-demo-layout-id]',body).forEach(e=>e.remove());return;}$$('.kodo-art-table-empty-placeholder,.demo-empty',table).forEach(e=>e.remove());body.replaceChildren();layouts.forEach(record=>{const row=document.createElement('div');row.className='kodo-art-table-row';row.dataset.demoLayoutId=record.id;row.style.cssText='display:flex;min-height:40px';[...head.children].forEach(h=>{const cell=document.createElement('div');cell.className='kodo-art-table-cell';cell.style.cssText=h.style.cssText;if(h.textContent.trim()==='操作'){for(const text of ['编辑','复制','删除']){const b=document.createElement('button');b.className='kodo-new-btn kodo-new-btn-text-primary';b.textContent=text;b.onclick=e=>{e.preventDefault();e.stopPropagation();if(text==='编辑')layoutEditor(b,record);else if(text==='复制'){layouts.push({id:'L-'+Date.now(),values:{...record.values,'布局名称':record.values['布局名称']+'（复制）'}});localStorage.setItem(layoutKey,JSON.stringify(layouts));renderLayouts();}else{layouts=layouts.filter(x=>x!==record);localStorage.setItem(layoutKey,JSON.stringify(layouts));renderLayouts();}};cell.append(b);}}else cell.textContent=record.values['布局名称']||'演示布局';row.append(cell);});body.append(row);});}
 C.initNativeForm=(top,name)=>{
  top.el.dataset.nativeForm=name;
  if(/^layout(?:Product|WO)$/.test(name)){top.el.style.background='white';wireLayout(top.d);const host=layoutHosts.get(top.d);if(host&&top.initial.__layoutMarkup)host.innerHTML=top.initial.__layoutMarkup;wireLayout(top.d);top.collect=values=>{values.__layoutFields=readLayoutValues(top.d);values.__layoutMarkup=layoutHosts.get(top.d)?.innerHTML||'';};}
  if(/^timeRule/.test(name)&&top.initial.__timeRanges){const list=$('.list-scroll__7kGSv',top.d);if(list){$$('.row__tGXSH',list).forEach(e=>e.remove());top.initial.__timeRanges.forEach(value=>{const holder=document.createElement('div');holder.innerHTML=A.components.timeRangeRow;const row=holder.firstElementChild;$('input[placeholder="开始时间"]',row).value=value.start;$('input[placeholder="结束时间"]',row).value=value.end;const box=$('input[type=checkbox]',row);if(box){box.checked=value.overtime;box.closest('.kodo-new-checkbox')?.classList.toggle('kodo-new-checkbox-checked',value.overtime);}list.append(row);});}}
  if(/^timeRule/.test(name))top.collect=values=>{values.__timeRanges=$$('.row__tGXSH',top.d).map(row=>({start:$('input[placeholder="开始时间"]',row)?.value||'',end:$('input[placeholder="结束时间"]',row)?.value||'',overtime:!!$('input[type=checkbox]:checked',row)}));};
 };
 document.addEventListener('click',e=>{
  const layer=e.target.closest('.demo-nested-layer[data-native-form]'),name=layer?.dataset.nativeForm;
  if(layer&&/^timeRule/.test(name)){
   const clock=e.target.closest('.kodo-new-picker-range');if(clock){const input=e.target.matches('input')?e.target:$('input',clock);if(input){e.preventDefault();e.stopImmediatePropagation();timePicker(input);return;}}const hit=e.target.closest('button,iconpark-icon');if(!hit)return;const text=norm(hit.textContent);
   if(text==='+添加时段'){e.preventDefault();e.stopImmediatePropagation();const holder=document.createElement('div');holder.innerHTML=A.components.timeRangeRow;const row=holder.firstElementChild;$('.list-scroll__7kGSv',layer)?.append(row);return;}
   if(text==='规则测试>'){e.preventDefault();e.stopImmediatePropagation();$('.right-pane__F97jK',layer).outerHTML=A.components.timeRuleTestPane;return;}
   if(hit.getAttribute('aria-label')==='返回'&&hit.closest('.right-pane__F97jK')){e.preventDefault();e.stopImmediatePropagation();$('.right-pane__F97jK',layer).outerHTML=A.components.timeRuleOverview;return;}
   const row=hit.closest('.row__tGXSH'),icon=hit.getAttribute('data-ui-icon')||$('iconpark-icon',hit)?.getAttribute('data-ui-icon');if(row&&/shanchu|delete/.test(icon||'')){e.preventDefault();e.stopImmediatePropagation();row.remove();return;}
  }
  if(layer&&/^layout(?:Product|WO)$/.test(name)){
   const hit=e.target.closest('button,.dragField__uQ02L');if(!hit)return;const text=norm(hit.textContent);
   if(text==='添加字段分组'){e.preventDefault();e.stopImmediatePropagation();C.openNativeForm('layoutGroup',hit,values=>{const target=$('.fieldRow__oMsKW',layer)?.parentElement;if(!target)return;const holder=document.createElement('div');holder.innerHTML=A.components.layoutGroupPanel;const section=holder.firstElementChild;$('.groupTitle__SHwqB',section).textContent=values['分组名称']||'演示分组';section.dataset.groupValues=JSON.stringify(values);target.append(section);wireLayout(layer);});return;}
   const group=hit.closest('.groupWrap__K3JLg');if(group&&text==='编辑'){e.preventDefault();e.stopImmediatePropagation();let values={};try{values=JSON.parse(group.dataset.groupValues||'{}');}catch{}C.openNativeForm('layoutGroup',hit,next=>{group.dataset.groupValues=JSON.stringify(next);$('.groupTitle__SHwqB',group).textContent=next['分组名称']||'演示分组';},values);return;}if(group&&hit.querySelector('[data-ui-icon=shanchu]')){e.preventDefault();e.stopImmediatePropagation();group.remove();wireLayout(layer);return;}
   if(text==='移除'){e.preventDefault();e.stopImmediatePropagation();const row=hit.closest('.fieldRow__oMsKW'),field=$('.fieldName__OVYm2',row)?.textContent.trim();row?.remove();$$('.dragField__uQ02L',layer).filter(x=>x.textContent.trim()===field).forEach(x=>x.classList.remove('canNotDrag___oFnX'));wireLayout(layer);return;}
   if(hit.matches('.dragField__uQ02L:not(.canNotDrag___oFnX)')){e.preventDefault();e.stopImmediatePropagation();addField(layer,hit.textContent.trim());return;}
  }
  if(layer||e.target.closest('.demo-bar,.demo-v3-portal,.demo-native-column-wrap'))return;
  const hit=e.target.closest('button,[class*=btn__]');if(!hit)return;const text=norm(hit.textContent);
  if(layoutPage&&text==='新建布局'){e.preventDefault();e.stopImmediatePropagation();layoutEditor(hit);return;}
  if(rulePage&&['新建规则','编辑'].includes(text)){e.preventDefault();e.stopImmediatePropagation();const row=hit.closest('[data-demo-record]');const initial=text==='编辑'?{...(C.getLocalRecord(row?.dataset.demoRecord)?.fields||{})}:{};if(row){initial['启用状态']=row.querySelector('[role=switch]')?.getAttribute('aria-checked')==='true'?'启用':'停用';if(String(initial['适用范围']).startsWith('全部'))initial['适用范围']='全部报工';}C.openNativeForm(text==='编辑'?'timeRuleEdit':'timeRuleCreate',hit,values=>{values['启用状态']=values['启用状态']==='启用';C.commitLocalRecord(values,row?.dataset.demoRecord);},initial);return;}
 },true);
 renderLayouts();document.documentElement.dataset.demoDetailReady='1';
})();
